// Reverse maps for Traditional to Simplified
const REVERSE_CHAR_MAP: Record<string, string> = {};
for (const [s, t] of Object.entries(CHAR_MAP)) {
  REVERSE_CHAR_MAP[t] = s;
}

const REVERSE_PHRASE_MAP: [string, string][] = PHRASE_MAP.map(([s, t]) => [t, s]);

/**
 * Convert string from Simplified to Traditional Chinese
 */
export function toTraditional(text: string): string {
  if (!text) return '';
  let result = text;
  
  // 1. Phrase replacement
  for (const [simp, trad] of PHRASE_MAP) {
    if (result.includes(simp)) {
      result = result.split(simp).join(trad);
    }
  }
  
  // 2. Character-by-character replacement
  let finalChars = '';
  for (let i = 0; i < result.length; i++) {
    const ch = result[i];
    finalChars += CHAR_MAP[ch] || ch;
  }
  
  return finalChars;
}

/**
 * Convert string from Traditional to Simplified Chinese
 */
export function toSimplified(text: string): string {
  if (!text) return '';
  let result = text;
  
  for (const [trad, simp] of REVERSE_PHRASE_MAP) {
    if (result.includes(trad)) {
      result = result.split(trad).join(simp);
    }
  }
  
  let finalChars = '';
  for (let i = 0; i < result.length; i++) {
    const ch = result[i];
    finalChars += REVERSE_CHAR_MAP[ch] || ch;
  }
  
  return finalChars;
}

/**
 * Language conversion helper based on target language
 */
export function convertText(text: string, targetLang: SupportedLang): string {
  if (!text) return '';
  if (targetLang === 'zh-Hant') {
    return toTraditional(text);
  }
  return toSimplified(text);
}
